 static String channelKey(String name){String s=Normalizer.normalize(name==null?"":name,Normalizer.Form.NFKC).toLowerCase(Locale.ROOT).replaceAll("(?i)(?:\\s|[-_])*(?:full\\s*hd|fhd|uhd|hd|sd|4k)\\s*$","").replaceAll("[^\\p{L}\\p{N}]","");if(s.equals("mbctwo"))s="mbc2";return s;}
